define([],function(){"use strict";const init=e=>{document.querySelectorAll(e).forEach(e=>{if("1"===e.dataset.initialized)return;e.dataset.initialized="1";const t=e.querySelector('[data-region="day-detail"]');e.querySelectorAll("[data-detail]").forEach(e=>{e.addEventListener("click",()=>{t&&(t.textContent=e.dataset.detail||"")})})})};return{init:init}});
